<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,StaffDuty,SupportCapability,StaffHandoverBatch as Batch};
use App\Support\{StaffHandover as H,StaffDuties,LearningAccess};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt,Notification};
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class StaffHandoverTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture(string $slot='tutor'):array {$m=User::factory()->create(['role'=>'admin']);$n=User::factory()->create(['role'=>'ceo']);$role=in_array($slot,['maths_tutor','english_tutor'],true)?'functional_skills_tutor':$slot;$old=User::factory()->create(['role'=>$role,'subject_scope'=>'both']);$to=User::factory()->create(['role'=>$role,'subject_scope'=>'both']);$a=Apprentice::factory()->create([$slot.'_id'=>$old->id,'email'=>'PRIVATE-LEARNER@example.test']);$b=Apprentice::factory()->create([$slot.'_id'=>$old->id]);return compact('m','n','old','to','a','b','slot');}
 private function prepare(array $f,?array $ids=null):Batch {return H::prepare($f['m'],1,$f['slot'],$f['old']->id,$f['to']->id,$ids??[$f['a']->id,$f['b']->id],'PRIVATE-HANDOVER-REFERENCE');}
 private function apply(array $f,Batch $b):void {H::decide($f['n'],1,$b,$b->version,'apply','PRIVATE-INDEPENDENT-CHECK');}
 private function invalid(callable $f):void {try{$f();$this->fail('Invalid operation accepted');}catch(ValidationException){$this->assertTrue(true);}}
 public function test_prepare_is_encrypted_exact_preview_with_no_assignment_changes_or_messages():void {$f=$this->fixture();Notification::fake();$b=$this->prepare($f);$this->assertSame('Pending',$b->state);$this->assertSame($f['old']->id,$f['a']->fresh()->tutor_id);$this->assertDatabaseCount('assignment_change_events',0);$this->assertDatabaseCount('staff_handover_events',1);$this->assertTrue(H::fresh($b));$raw=DB::table('staff_handover_batches')->value('source');$this->assertStringNotContainsString('PRIVATE-HANDOVER',$raw);$this->assertStringNotContainsString('PRIVATE-LEARNER',Crypt::decryptString($raw));$this->assertCount(2,$b->source['rows']);Notification::assertNothingSent();}
 public function test_different_manager_applies_every_selected_row_once_and_records_canonical_history():void {$f=$this->fixture();$b=$this->prepare($f);$before=$f['a']->fresh()->getAttributes();$this->apply($f,$b);$b->refresh();$this->assertTrue(H::applied($b));$this->assertSame($f['to']->id,$f['a']->fresh()->tutor_id);$this->assertSame($f['to']->id,$f['b']->fresh()->tutor_id);$this->assertSame(2,$f['a']->fresh()->version);$this->assertDatabaseCount('assignment_change_events',2);$this->assertDatabaseHas('audit_events',['event'=>'staff_handover_applied']);foreach($before as$key=>$value){if(!in_array($key,['tutor_id','version','updated_at'],true)){$this->assertSame($value,$f['a']->fresh()->getAttributes()[$key]);}}$this->invalid(fn()=>H::decide($f['n'],1,$b,1,'apply','Replay'));}
 public function test_creator_cannot_apply_or_reject_own_preview():void {$f=$this->fixture();$b=$this->prepare($f);foreach(['apply','reject']as$d){$this->invalid(fn()=>H::decide($f['m'],1,$b,1,$d,'Self-check'));}$this->assertSame('Pending',$b->fresh()->state);}
 public function test_creator_can_withdraw_and_peer_can_reject_without_changing_learners():void {$f=$this->fixture();$b=$this->prepare($f);H::decide($f['m'],1,$b,1,'withdraw','Withdraw synthetic');$this->assertSame('Withdrawn',$b->fresh()->state);$c=$this->prepare($f);H::decide($f['n'],1,$c,1,'reject','Reject synthetic');$this->assertSame('Rejected',$c->fresh()->state);$this->assertDatabaseCount('assignment_change_events',0);}
 public function test_one_changed_profile_blocks_whole_batch_without_partial_application():void {$f=$this->fixture();$b=$this->prepare($f);$f['b']->version++;$f['b']->save();$this->assertFalse(H::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));$this->assertSame($f['old']->id,$f['a']->fresh()->tutor_id);$this->assertDatabaseCount('assignment_change_events',0);$this->assertSame('Pending',$b->fresh()->state);}
 public function test_raw_profile_change_even_without_version_bump_stales_preview():void {$f=$this->fixture();$b=$this->prepare($f);DB::table('apprentices')->where('id',$f['a']->id)->update(['first_name'=>'Changed']);$this->assertFalse(H::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));}
 public function test_target_deactivation_role_subject_or_duty_change_blocks_apply():void {foreach(['active','role','subject_scope']as$field){$f=$this->fixture('maths_tutor');$b=$this->prepare($f);$u=$f['to'];$u->$field=['active'=>false,'role'=>'staff','subject_scope'=>'english'][$field];$u->save();$this->assertFalse(H::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));}}
 public function test_source_staff_identity_change_and_creator_auth_change_stale_preview():void {$f=$this->fixture();$b=$this->prepare($f);$f['old']->name='Changed source';$f['old']->save();$this->assertFalse(H::fresh($b));$c=$this->prepare($f);$f['m']->auth_version=2;$f['m']->save();$this->assertFalse(H::fresh($c));$this->invalid(fn()=>$this->apply($f,$c));}
 public function test_expiry_is_read_only_and_expired_preview_can_be_withdrawn():void {$f=$this->fixture();$b=$this->prepare($f);$this->travel(25)->hours();$this->assertFalse(H::fresh($b));$this->assertSame('Pending',$b->fresh()->state);$this->invalid(fn()=>$this->apply($f,$b));H::decide($f['m'],1,$b,1,'withdraw','Expired');$this->assertSame('Withdrawn',$b->fresh()->state);}
 public function test_all_five_slots_and_unassigned_source_support_only_eligible_staff():void {foreach(array_keys(H::SLOTS)as$slot){$f=$this->fixture($slot);$f['a']->{$slot.'_id'}=null;$f['a']->save();$b=H::prepare($f['m'],1,$slot,null,$f['to']->id,[$f['a']->id],'Synthetic named unassigned');$this->apply($f,$b);$this->assertSame($f['to']->id,$f['a']->fresh()->{$slot.'_id'});$this->assertSame($f['old']->id,$f['b']->fresh()->{$slot.'_id'});}}
 public function test_additional_duty_is_eligible_but_never_auto_granted():void {$f=$this->fixture('careers_adviser');$u=User::factory()->create(['role'=>'staff']);$this->assertFalse(H::eligible($u,'careers_adviser'));StaffDuties::save($u,$f['m'],1,1,0,['careers_adviser'=>true]);$f['to']=$u->fresh();$b=$this->prepare($f);$this->apply($f,$b);$this->assertSame('staff',$u->fresh()->role);$this->assertSame($u->id,$f['a']->fresh()->careers_adviser_id);}
 public function test_inactive_source_can_be_handed_over_but_same_target_or_wrong_source_refuse():void {$f=$this->fixture();$f['old']->active=false;$f['old']->save();$b=$this->prepare($f);$this->assertTrue(H::fresh($b));$this->invalid(fn()=>H::prepare($f['m'],1,'tutor',$f['old']->id,$f['old']->id,[$f['a']->id],'Same'));$this->invalid(fn()=>H::prepare($f['m'],1,'tutor',null,$f['to']->id,[$f['a']->id],'Wrong source'));}
 public function test_unknown_slot_empty_duplicates_oversize_and_missing_rows_refuse():void {$f=$this->fixture();foreach([[],[$f['a']->id,$f['a']->id],range(1000,1100),[999999]]as$ids){$this->invalid(fn()=>$this->prepare($f,$ids));}$this->invalid(fn()=>H::prepare($f['m'],1,'employer',$f['old']->id,$f['to']->id,[$f['a']->id],'Bad slot'));$this->assertDatabaseCount('staff_handover_batches',0);}
 public function test_existing_inclusion_duty_is_flagged_and_changed_capability_stales_preview():void {$f=$this->fixture();$c=SupportCapability::create(['user_id'=>$f['to']->id,'duty'=>'member','scope'=>'assigned','apprentice_ids'=>[],'group_ids'=>[]]);$b=$this->prepare($f);$this->assertTrue($b->source['support_impact']);$c->scope='all';$c->version=2;$c->save();$this->assertFalse(H::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));}
 public function test_source_or_plaintext_metadata_corruption_never_applies_or_looks_verified():void {$f=$this->fixture();$b=$this->prepare($f);DB::table('staff_handover_batches')->where('id',$b->id)->update(['target_user_id'=>$f['old']->id]);$b->refresh();$this->assertFalse(H::intact($b));$this->invalid(fn()=>$this->apply($f,$b));$this->actingAs($f['m'])->get('/staff-handovers/'.$b->id)->assertStatus(409);}
 public function test_forged_applied_plaintext_state_has_no_verified_receipt_or_staff_names():void {$f=$this->fixture();$b=$this->prepare($f);DB::table('staff_handover_batches')->where('id',$b->id)->update(['state'=>'Applied']);$b->refresh();$this->assertFalse(H::applied($b));$this->assertSame([],H::incomingScope($b,$f['to'])['rows']);}
 public function test_required_assignment_audit_failure_rolls_back_all_rows_and_batch():void {$f=$this->fixture();$b=$this->prepare($f);AuditFault::install('handover_assignment_fault','assignment_change_events','Synthetic fail');try{$this->apply($f,$b);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertSame($f['old']->id,$f['a']->fresh()->tutor_id);$this->assertSame($f['old']->id,$f['b']->fresh()->tutor_id);$this->assertSame('Pending',$b->fresh()->state);}
 public function test_required_batch_event_failure_rolls_back_receipt_and_assignments():void {$f=$this->fixture();$b=$this->prepare($f);AuditFault::install('handover_event_fault','staff_handover_events','Synthetic fail','preview_apply');try{$this->apply($f,$b);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertSame($f['old']->id,$f['a']->fresh()->tutor_id);$this->assertDatabaseCount('assignment_change_events',0);$this->assertSame('Pending',$b->fresh()->state);}
 public function test_two_same_source_batches_cannot_both_apply():void {$f=$this->fixture();$a=$this->prepare($f);$b=$this->prepare($f);$this->apply($f,$a);$this->assertFalse(H::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));$this->assertDatabaseCount('assignment_change_events',2);}
 public function test_active_manager_and_auth_versions_rechecked_in_service():void {$f=$this->fixture();$b=$this->prepare($f);$f['n']->auth_version=2;$f['n']->save();try{$this->apply($f,$b);$this->fail('Stale actor');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}$f['n']->role='tutor';$f['n']->save();try{H::decide($f['n'],2,$b,1,'apply','Wrong role');$this->fail('Wrong actor');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}}
 public function test_workload_counts_all_profiles_and_separates_roles_without_capacity_claim():void {$f=$this->fixture();$f['a']->mentor_id=$f['old']->id;$f['a']->save();$snap=H::workload($f['m']);$row=collect($snap['rows'])->first(fn($r)=>$r['user']->id===$f['old']->id);$this->assertSame(2,$row['slots']['tutor']['count']);$this->assertSame(1,$row['slots']['mentor']['count']);$this->assertFalse($row['slots']['mentor']['eligible']);$this->assertStringContainsString('not FTE',$snap['meaning']);}
 public function test_manager_pages_search_escape_privacy_and_read_only_requests():void {$f=$this->fixture();$b=$this->prepare($f);$this->actingAs($f['m'])->get('/staff-handovers')->assertOk()->assertHeader('Referrer-Policy','no-referrer');$this->get('/staff-handovers/workload')->assertOk()->assertDontSee('PRIVATE-LEARNER');$this->get('/staff-handovers/new?slot=tutor&from='.$f['old']->id)->assertOk()->assertSee($f['a']->reference);$this->get('/staff-handovers/new?slot=tutor&from='.$f['old']->id.'&search=%25')->assertOk()->assertDontSee($f['a']->reference);$this->get('/staff-handovers/'.$b->id)->assertOk()->assertSee('PRIVATE-HANDOVER-REFERENCE')->assertDontSee('PRIVATE-LEARNER')->assertDontSee($f['to']->email);$this->assertDatabaseCount('assignment_change_events',0);}
 public function test_ordinary_staff_and_learners_cannot_use_manager_routes_or_export():void {$f=$this->fixture();$b=$this->prepare($f);foreach(['tutor','mentor','careers_adviser','staff','apprentice','employer']as$role){$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/staff-handovers')->assertForbidden();$this->get('/staff-handovers/workload')->assertForbidden();$this->get('/staff-handovers/new')->assertForbidden();$this->get('/staff-handovers/'.$b->id)->assertForbidden();$this->get('/staff-handovers/'.$b->id.'/handover.json')->assertForbidden();$this->post('/staff-handovers',[])->assertForbidden();$this->post('/staff-handovers/'.$b->id,[])->assertForbidden();}}
 public function test_minimal_export_contains_no_reason_notes_seals_or_private_evidence():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$this->actingAs($f['m'])->get('/staff-handovers/'.$b->id.'/handover.json')->assertOk()->assertJsonPath('applied_proof_verified',true)->assertJsonPath('private_notes_and_identity_seals_exported',false)->assertDontSee('PRIVATE-')->assertDontSee('profile_hash')->assertHeader('Cache-Control','no-store, private');}
 public function test_own_incoming_shows_only_own_current_assignments_no_manager_reason_or_other_batch():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$other=$this->fixture();$c=$this->prepare($other);$this->apply($other,$c);$this->actingAs($f['to'])->get('/my-staff-handovers')->assertOk()->assertSee($f['a']->reference)->assertDontSee($other['a']->reference)->assertDontSee('PRIVATE-HANDOVER')->assertDontSee('PRIVATE-INDEPENDENT');}
 public function test_recipient_acknowledges_and_clears_exact_current_scope_without_business_completion():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();$scope=H::incomingScope($b,$f['to']);H::acknowledge($f['to'],1,$b,0,$scope['hash'],true);$this->assertNotNull(H::acknowledgement($b,$f['to'],$scope)['acknowledged_at']);$this->assertTrue(H::applied($b->fresh()));H::acknowledge($f['to'],1,$b,1,$scope['hash'],false);$this->assertNull(H::acknowledgement($b,$f['to'],$scope)['acknowledged_at']);$this->assertSame(2,$f['a']->fresh()->version);$this->assertDatabaseCount('assignment_change_events',2);$this->assertDatabaseCount('staff_handover_events',4);}
 public function test_acknowledgement_scope_shrinks_when_learner_moves_and_old_form_refuses():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();$scope=H::incomingScope($b,$f['to']);H::acknowledge($f['to'],1,$b,0,$scope['hash'],true);$f['a']->refresh();$f['a']->tutor_id=$f['old']->id;$f['a']->version++;$f['a']->save();$new=H::incomingScope($b,$f['to']);$this->assertCount(1,$new['rows']);$this->assertTrue((bool)H::acknowledgement($b,$f['to'],$new)['needs_recheck']);$this->invalid(fn()=>H::acknowledge($f['to'],1,$b,1,$scope['hash'],true));$this->actingAs($f['to'])->get('/my-staff-handovers')->assertOk()->assertDontSee($f['a']->reference)->assertSee($f['b']->reference);}
 public function test_wrong_staff_and_managers_cannot_acknowledge_for_target():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();$scope=H::incomingScope($b,$f['to']);foreach([$f['old'],$f['m'],User::factory()->create(['role'=>'employer'])]as$u){$this->actingAs($u)->post('/my-staff-handovers/'.$b->id,['version'=>0,'scope_hash'=>$scope['hash'],'confirmed'=>1])->assertForbidden();}$this->assertDatabaseCount('staff_handover_acknowledgements',0);}
 public function test_no_current_assignment_or_lost_duty_means_no_names_and_no_acknowledgement():void {$f=$this->fixture('mentor');$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();$old=H::incomingScope($b,$f['to']);$f['to']->role='staff';$f['to']->save();$this->assertSame([],H::incomingScope($b,$f['to'])['rows']);$this->invalid(fn()=>H::acknowledge($f['to'],1,$b,0,$old['hash'],true));$this->actingAs($f['to'])->get('/my-staff-handovers')->assertOk()->assertDontSee($f['a']->reference);}
 public function test_ack_audit_failure_rolls_back_confirmation_and_does_not_change_application():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();AuditFault::install('handover_ack_fault','staff_handover_events','Synthetic fail','recipient_acknowledged');try{H::acknowledge($f['to'],1,$b,0,H::incomingScope($b,$f['to'])['hash'],true);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('staff_handover_acknowledgements',0);$this->assertTrue(H::applied($b->fresh()));}
 public function test_post_validation_requires_exact_selection_confirmation_and_notes():void {$f=$this->fixture();$data=['slot'=>'tutor','from'=>$f['old']->id,'target'=>$f['to']->id,'apprentices'=>[$f['a']->id],'reason'=>'Fictional','confirmed'=>1];$this->actingAs($f['m']);foreach(['apprentices','reason','confirmed']as$key){$d=$data;unset($d[$key]);$this->post('/staff-handovers',$d)->assertSessionHasErrors($key);}$this->assertDatabaseCount('staff_handover_batches',0);}
 public function test_stale_decision_and_ack_versions_do_not_mutate():void {$f=$this->fixture();$b=$this->prepare($f);$this->invalid(fn()=>H::decide($f['n'],1,$b,2,'apply','Stale'));$this->apply($f,$b);$b->refresh();$scope=H::incomingScope($b,$f['to']);H::acknowledge($f['to'],1,$b,0,$scope['hash'],true);$this->invalid(fn()=>H::acknowledge($f['to'],1,$b,0,$scope['hash'],true));$this->assertDatabaseCount('staff_handover_acknowledgements',1);}
 public function test_prepare_audit_failure_rolls_back_preview():void {$f=$this->fixture();AuditFault::install('handover_preview_fault','staff_handover_events','Synthetic fail');try{$this->prepare($f);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('staff_handover_batches',0);}
 public function test_incoming_is_empty_before_application_and_malformed_routes_are_guarded():void {$f=$this->fixture();$b=$this->prepare($f);$this->actingAs($f['to'])->get('/my-staff-handovers')->assertOk()->assertDontSee($f['a']->reference);$this->actingAs($f['m'])->get('/staff-handovers/new?slot=employer')->assertSessionHasErrors('slot');$this->get('/staff-handovers?state=bad')->assertSessionHasErrors('state');$this->get('/staff-handovers/not-a-uuid')->assertNotFound();}
 public function test_plaintext_ack_time_and_preview_expiry_tamper_cannot_look_current():void {$f=$this->fixture();$b=$this->prepare($f);DB::table('staff_handover_batches')->where('id',$b->id)->update(['expires_at'=>now()->addDays(5)]);$this->assertFalse(H::intact($b->fresh()));$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();$scope=H::incomingScope($b,$f['to']);H::acknowledge($f['to'],1,$b,0,$scope['hash'],true);DB::table('staff_handover_acknowledgements')->update(['acknowledged_at'=>now()->addDay()]);$this->assertNull(H::acknowledgement($b,$f['to'],$scope)['acknowledged_at']);$this->assertTrue((bool)H::acknowledgement($b,$f['to'],$scope)['needs_recheck']);}

}
